cat > /tmp/x.py <<'EOF'
import re,glob,os
M={'info':'neutral','success':'positive','warning':'caution'}
tag=re.compile(r'<app-pill(?![\w-])((?:[^>"\']|"[^"]*"|\'[^\']*\')*?)(/?)>(\s*</app-pill>)?',re.S)
attr=re.compile(r'([\[\]\w.-]+)(?:\s*=\s*(?:"([^"]*)"|\'([^\']*)\'))?')
def neg(e):
    e=e.strip()
    if e=='true':return 'false'
    if e=='false':return 'true'
    m=re.fullmatch(r'!\s*\((.*)\)',e,re.S)
    if m and balanced(m.group(1)):return m.group(1)
    if re.fullmatch(r'![\w.?\[\]\'"()]+',e):return e[1:]
    if re.fullmatch(r'[\w.?\[\]\'"]+(\(\))?',e):return '!'+e
    return '!('+e+')'
def balanced(s):
    d=0
    for c in s:
        d+= c=='('; d-= c==')'
        if d<0:return False
    return d==0
def tone(e):
    if re.fullmatch(r"\s*'\w+'\s*|.*\?.*:.*",e,re.S) and "'" in e:
        return re.sub(r"'(info|success|warning)'",lambda m:"'%s'"%M[m.group(1)],e),False
    return e+' | pillTone',True
used=set()
def sub(m,f):
    body,self_,_=m.group(1),m.group(2),m.group(3)
    out=[];content=''
    for a in attr.finditer(body):
        n=a.group(1);v=a.group(2) if a.group(2) is not None else a.group(3)
        if n=='disableTooltip':out.append('tooltip="%s"'%('false' if v=='true' else 'true') if False else None) or out.pop(); out.append('[tooltip]="%s"'%neg(v))
        elif n=='[disableTooltip]':out.append('[tooltip]="%s"'%neg(v))
        elif n=='variant':out.append('tone="%s"'%M[v])
        elif n=='[variant]':
            t,p=tone(v);out.append('[tone]="%s"'%t)
            if p:used.add(f)
        elif n=='label':content=v
        elif n=='[label]':content='{{ %s }}'%v
        else:out.append(a.group(0))
    q='"' 
    return '<app-pill'+''.join(' '+o for o in out)+'>'+content+'</app-pill>'
files=glob.glob('src/app/features/*/*.ts')+glob.glob('src/app/features/*/*.html')
for f in files:
    s=open(f).read()
    if '<app-pill' not in s:continue
    n=tag.sub(lambda m:sub(m,f),s)
    open(f,'w').write(n)
for f in used:
    ts=f if f.endswith('.ts') else f[:-5]+'.ts'
    s=open(ts).read()
    s=re.sub(r'imports:\s*\[\s*',lambda m:m.group(0)+'PillTonePipe, ',s,1)
    s=re.sub(r'(import \{[^}]*PillComponent[^}]*\} from "../../lib/pill.component";\n)',r'\1import { PillTonePipe } from "../../lib/pill-tone.pipe";\n',s,1)
    open(ts,'w').write(s)
EOF
